import{_ as c}from"./chunks/inter_core_sync_scenario_example.CZKU2nm-.js";import{_}from"./chunks/block_subblock_relationship_3510.CppXQqub.js";import{_ as d,o,a as e,b as r}from"./app.DKoEZOcr.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"核间同步能力概述","link":"/api/SIMD-API/c_api/sync/inter_core_sync_overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/inter_core_sync_overview.md","filePath":"api/SIMD-API/c_api/sync/inter_core_sync_overview.md","lastUpdated":1787539100000}'),a={name:"api/SIMD-API/c_api/sync/inter_core_sync_overview.md"};function s(i,t,b,n,l,I){return o(),e("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>核间同步能力概述</h1><p>核间同步的使用场景通常是：一个核计算所依赖的数据，需要等待其他相关核的计算全部完成后才能获取。</p><p>以图1为例，AIC需要依赖AIV的<code>asc_reduce</code>计算结果。由于整体矢量较大，必须拆分为多个部分，由每个AIV分别完成部分计算。每个AIV将其部分计算结果通过原子累加写入GM。AIC必须读取所有AIV均完成累加后的最终结果，因此需要通过核间同步来保证AIC读取<code>asc_reduce</code>结果时的时序正确性。</p><p><strong>图1</strong> 核间同步业务场景示例图（AIC与AIV的比例为1：2）<br><img src="'+c+'" alt></p><p>AIC/AIV多核结构如下图2所示，AIC/AIV按group划分。一个group内细分block及subblock，block与subblock比例为1：N（N≥1），block表示多少个“主核”，subblock表示一个“主核”带多少个“从核”。</p><p>算子按计算特征可分为三类：Cube算子（矩阵计算）、Vector算子（矢量计算）和Mix算子（同时包含矩阵和矢量计算）。如表1所示，算子类型决定了其所需的核间同步方式和可选的group配置模式。其中Mix算子通过函数修饰符指定AIC与AIV的block/subblock关系；Cube算子和Vector算子为单类核执行，不涉及block/subblock划分。AIV为block且AIC为subblock的配置（即Vector核为主、Cube核为辅的模式）当前不支持。表2总结了核间同步接口及其支持的同步场景。</p><p><strong>图2</strong> block和subblock之间关系（灰色部分表示一个group，即1个block和N个subblock）<span id="fig_block_subblock_relationship"></span><br><img src="'+_+'" alt></p><p><strong>表1</strong> group配置</p><table><thead><tr><th>算子类型</th><th>函数修饰符</th><th>Kernel类型</th><th>block/subblock</th><th>1：N</th></tr></thead><tbody><tr><td>Cube算子</td><td><code>__cube__</code></td><td><code>KERNEL_TYPE_AIC_ONLY</code></td><td>AIC为block，无subblock</td><td>不涉及</td></tr><tr><td>Vector算子</td><td><code>__vector__</code></td><td><code>KERNEL_TYPE_AIV_ONLY</code></td><td>AIV为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td><code>__mix__(1, 0)</code></td><td><code>KERNEL_TYPE_MIX_AIC_1_0</code></td><td>AIC为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td><code>__mix__(0, 1)</code></td><td><code>KERNEL_TYPE_MIX_AIV_1_0</code></td><td>AIV为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td><code>__mix__(1, 1)</code></td><td><code>KERNEL_TYPE_MIX_AIC_1_1</code></td><td>AIC为block，AIV为subblock</td><td>1：1</td></tr><tr><td>Mix算子</td><td><code>__mix__(1, 2)</code></td><td><code>KERNEL_TYPE_MIX_AIC_1_2</code></td><td>AIC为block，AIV为subblock</td><td>1：2</td></tr></tbody></table><p><strong>表2</strong> 支持的核间同步场景</p><table><thead><tr><th>接口名称</th><th>同步范围</th><th>对应模式</th><th>功能简述</th></tr></thead><tbody><tr><td><a href="asc_sync_inter_arrive.html">asc_sync_inter_arrive</a>/<a href="asc_sync_inter_wait.html">asc_sync_inter_wait</a></td><td>组间同步，即不同group之间所有block（所有AIC或所有AIV）之间的同步。</td><td>模式0（同步等待全部AIC或全部AIV执行结束）</td><td><code>asc_sync_inter_arrive</code>为生产者，负责发送通知；<code>asc_sync_inter_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="asc_sync_subblock_arrive.html">asc_sync_subblock_arrive</a>/<a href="asc_sync_subblock_wait.html">asc_sync_subblock_wait</a></td><td>组内subblock间的同步，即同一group内不同subblock（AIV）之间的同步。</td><td>模式1（单个AI Core内，全部AIV之间的同步）</td><td><code>asc_sync_subblock_arrive</code>为生产者，负责发送通知；<code>asc_sync_subblock_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="asc_sync_block_arrive.html">asc_sync_block_arrive</a>/<a href="asc_sync_block_wait.html">asc_sync_block_wait</a></td><td>同一group内block（AIC）与所有subblock（AIV）之间的同步。</td><td>模式2（单个AI Core内，AIC与全部AIV之间的同步）</td><td><code>asc_sync_block_arrive</code>为生产者，负责发送通知；<code>asc_sync_block_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="asc_sync_intra_arrive.html">asc_sync_intra_arrive</a>/<a href="asc_sync_intra_wait.html">asc_sync_intra_wait</a></td><td>同一group内block（AIC）与单个subblock（AIV）之间的同步。</td><td>模式4（单个AI Core内，AIC核与单个AIV之间同步）</td><td><code>asc_sync_intra_arrive</code>为生产者，负责发送通知；<code>asc_sync_intra_wait</code>为消费者，负责阻塞等待通知到达。</td></tr></tbody></table></article></div>',1)])])}const h=d(a,[["render",s]]);export{u as __pageData,h as default};
